import java.util.*;

class Solution {
    public int[] cheapestNeighbor(int n, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});   // directed: one direction only
        }
        int[] res = new int[n];
        for (int u = 0; u < n; u++) {
            res[u] = -1;
            int bestW = Integer.MAX_VALUE;
            for (int[] e : adj.get(u)) {
                int v = e[0], w = e[1];
                if (w < bestW || (w == bestW && v < res[u])) {
                    bestW = w;
                    res[u] = v;
                }
            }
        }
        return res;
    }
}

